ation": "Giữa vô số từ mượn từ tiếng Pháp, tiếng Latinh, tiếng Bắc Âu cổ và các ngôn ngữ khác, khó mà nhận ra cội nguồn của tiếng Anh hiện đại. Ngôn ngữ học so sánh giúp ta làm điều đó bằng cách chú ý đến cấu trúc ngữ pháp, quy luật biến đổi âm thanh và một số từ vựng cốt lõi.", "contentStale": false, "manualFields": ["TRANSLATION"], "timingSource": null, "coarseStartMs": 102940, "manualLocales": {}, "manualSources": {}, "thoughtGroups": [], "cefrSuggestion": "B2", "ipaNeedsReview": true, "contentWarnings": [], "dictationEligible": true, "dictationPriority": null, "dictationSelected": true, "ipaDisplayVersion": "learner-ipa-v1", "shadowingEligible": true, "shadowingPriority": null, "shadowingSelected": true, "contentTypeSuggestion": "MONOLOGUE"}, {"id": "9b13460b-344b-4b33-982b-a2498bc8ef87", "ipa": "fɔːr ɛɡzˈæmpəl ˈæftɚ ðə sˈɪksθ sˈɛntʃɚri dʒˈɜːmən wˈɜːdz stˈɑːrɾɪŋ wɪð pˈiː sˌɪstəmˈæɾɪkli ʃˈɪft(ɪ/ə)d tʊ ɐ pˌiːˈɛf sˈaʊnd wˌaɪl ðɛr ˈoʊld ˈɪŋɡlɪʃ kˈaʊntɚpˌɑːrts kˈɛpt ðə pˈiː ʌntʃˈeɪndʒd", "text": "For example, after the sixth century, German words starting with p systematically shifted to a pf sound, while their Old English counterparts kept the p unchanged.", "cloze": {"easy": [2, 5, 8, 12, 22], "text": "For example, after the sixth century, German words starting with p systematically shifted to a pf sound, while their Old English counterparts kept the p unchanged.", "medium": [1, 2, 4, 5, 8, 12, 17, 21, 22, 25], "version": "cloze-v2", "textHash": "612c28817ba79e981162c93317c1bb36dcd51e1ba7ff0a2d28d5e5336ca0827e"}, "hints": [], "notes": [], "usage": "LEARN", "words": [{"text": "For", "endMs": 121400, "charEnd": 3, "startMs": 121160, "tokenEnd": 1, "charStart": 0, "tokenStart": 0}, {"text": "example", "endMs": 121880, "charEnd": 11, "startMs": 121400, "tokenEnd": 2, "charStart": 4, "tokenStart": 1}, {"text": "after", "endMs": 122520, "charEnd": 18, "startMs": 122200, "tokenEnd": 3, "charStart": 13, "tokenStart": 2}, {"text": "the", "endMs": 122600, "charEnd": 22, "sta